@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#f4f1e8;--muted:#a9bac0;--gold:#edc879;--navy:#081a28;--panel:rgba(7,24,37,.88);--line:rgba(226,207,161,.21)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071a29;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#092236;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;top:0;left:0;right:0;height:76px;padding:0 28px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(5,19,30,.94),rgba(5,19,30,.58));border-bottom:1px solid rgba(255,255,255,.09);z-index:3}.brand{display:flex;align-items:center;gap:11px;letter-spacing:1.6px;font-size:12px}.brand b{display:block;font-size:11px;letter-spacing:2px}.brand small{display:block;color:#9eb0b4;font-size:8px;letter-spacing:3.3px;margin-top:3px}.brand-mark{width:37px;height:37px;border:1px solid #d5b874;border-radius:50%;display:grid;place-items:center;color:#e3c781;font-size:19px;box-shadow:0 0 18px #d5b87422}.player-chip{display:flex;align-items:center;gap:10px;position:absolute;left:50%;transform:translateX(-50%);background:rgba(255,255,255,.055);padding:7px 16px 7px 8px;border:1px solid rgba(255,255,255,.1);border-radius:8px;min-width:160px}.avatar-mini{width:32px;height:32px;background:linear-gradient(145deg,#eacb87,#a87945);border-radius:50%;display:grid;place-items:center;color:#17424a}.player-chip strong{font-size:11px;display:block}.player-chip small{font-size:8px;color:#b8c5c6;letter-spacing:1.5px}.top-actions{display:flex;gap:8px}.icon-btn{width:34px;height:34px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);border-radius:8px;font-size:17px;color:#d9d4c7}.icon-btn:hover,.rail-button:hover{background:#ffffff1a}.hud-left{position:absolute;z-index:2;left:26px;top:99px;width:232px;display:flex;flex-direction:column;gap:12px}.status-card,.quest-card{background:var(--panel);border:1px solid var(--line);border-radius:11px;backdrop-filter:blur(8px);box-shadow:0 10px 28px #06131c35}.status-card{padding:14px 15px 13px}.stat-line{display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:1.2px;color:#bac6c6}.stat-line b{margin-left:auto;font-size:9px;color:#f5eee0;letter-spacing:.3px}.heart{font-size:14px;color:#ed7770}.energy-icon{font-size:14px;color:#77dce0}.meter{height:5px;border-radius:5px;background:#ffffff1a;margin:6px 0 12px;overflow:hidden}.meter i{height:100%;display:block;width:100%;border-radius:5px;background:linear-gradient(90deg,#d95c61,#ef8c81);transition:width .2s}.meter.energy i{background:linear-gradient(90deg,#2e9fa8,#7de0d4)}.xp-label{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.2px;color:#bdc6c1;margin-top:1px}.xp-label b{color:#e6d3a5;font-size:9px;letter-spacing:0}.meter.xp{height:4px;margin:6px 0 0}.meter.xp i{background:linear-gradient(90deg,#d9ab57,#f2d594)}.quest-card{padding:13px 15px 12px}.quest-head{display:flex;align-items:center;gap:9px}.quest-icon{width:28px;height:28px;display:grid;place-items:center;background:#e8c8791c;border-radius:7px;color:#eaca7e;font-size:16px}.quest-head small{display:block;font-size:7px;letter-spacing:1.6px;color:#d2b96e;margin-bottom:3px}.quest-head b{font-size:11px}.quest-card p{font-size:10px;color:#c0ccca;margin:12px 0 8px}.quest-progress{display:flex;align-items:center;gap:8px;font-size:9px;color:#e8d59b}.quest-progress .meter{height:4px;flex:1;margin:0}.quest-progress .meter i{background:#d9b866;width:0}.quest-btn{width:100%;margin-top:12px;background:transparent;border:1px solid #e8c87955;border-radius:6px;color:#e7cd89;font-size:8px;letter-spacing:1.4px;padding:8px}.quest-btn span{float:right;font-size:12px;margin-top:-3px}.location-pill{position:absolute;z-index:2;top:91px;left:50%;transform:translateX(-50%);border:1px solid #f4e3b433;background:#0a2335b8;border-radius:30px;padding:8px 14px;display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:1.5px;color:#e9dfc9;white-space:nowrap;backdrop-filter:blur(5px)}.location-dot{width:6px;height:6px;background:#a9d8a5;border-radius:50%;box-shadow:0 0 8px #a9d8a5}.location-divider{color:#d7b768}.right-rail{position:absolute;right:24px;top:105px;z-index:3;display:flex;flex-direction:column;gap:8px}.rail-button{width:57px;height:58px;background:var(--panel);border:1px solid var(--line);border-radius:9px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:#d8d1bd}.rail-button span{font-size:17px}.rail-button small{font-size:7px;letter-spacing:1.3px}.rail-button.active{border-color:#e4c47d88;color:#efd38e;box-shadow:inset 0 0 16px #dbbd6b14}.bottom-ui{position:absolute;z-index:3;left:50%;bottom:22px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:10px}.hint{display:flex;align-items:center;gap:7px;color:#e0e5df;font-size:8px;letter-spacing:1px;text-shadow:0 2px 6px #000}.hint i{width:1px;height:12px;background:#ffffff4a;margin:0 5px}.keycap{background:#071d2dce;border:1px solid #d5d9d744;border-radius:4px;padding:4px 6px;font-size:8px;color:#f1d992}.hotbar{display:flex;gap:7px}.hotkey{position:relative;width:69px;height:67px;border:1px solid #e3d2ad56;border-radius:9px;background:linear-gradient(145deg,#122b3bde,#0a1e2cde);display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 5px 15px #0005}.hotkey .slot-key{position:absolute;top:4px;left:6px;color:#e8d18f;font-size:8px;font-weight:700}.slot-icon{font-size:24px;line-height:28px;color:#e4d7b7;text-shadow:0 0 13px #d8c28a66}.slot-icon.fire{color:#ffad6e;text-shadow:0 0 14px #f46539aa}.slot-icon.wave{color:#78dadd;text-shadow:0 0 14px #48b4beaa}.slot-icon.potion{color:#8ed8ca}.hotkey small{font-size:7px;letter-spacing:.7px;color:#d0d5cf;margin-top:2px}.power-slot{border-color:#e7bd766b}.potion-slot{cursor:pointer}.cooldown{position:absolute;inset:0;border-radius:8px;background:rgba(5,15,23,.68);transform-origin:bottom;transform:scaleY(0);pointer-events:none}.toast{position:absolute;z-index:8;top:76px;left:50%;transform:translate(-50%,-20px);padding:10px 18px;border:1px solid #e2c7776b;border-radius:7px;background:#102d3ceF;color:#f2dda0;font-size:11px;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction{position:absolute;z-index:2;left:50%;top:48%;color:#fff3ce;font-size:10px;text-shadow:0 1px 5px #000}.panel{display:none;position:absolute;z-index:7;right:98px;top:98px;width:300px;min-height:180px;padding:20px;background:#0b2232f2;border:1px solid #d9bf7955;border-radius:12px;box-shadow:0 14px 50px #0009;backdrop-filter:blur(12px)}.panel.open{display:block;animation:pop .18s ease-out}.panel-close{position:absolute;right:10px;top:8px;border:0;background:none;color:#c2c8bc;font-size:22px}.panel h2{font:700 22px 'Playfair Display',serif;margin:3px 0 5px;color:#f0d99c}.panel .sub{font-size:10px;color:#aab8b8;margin:0 0 17px}.item-row{border:1px solid #ffffff16;background:#ffffff08;border-radius:8px;padding:11px;margin:8px 0;display:flex;align-items:center;gap:10px}.item-art{width:40px;height:40px;background:#173c48;border-radius:8px;display:grid;place-items:center;color:#e5c877;font-size:22px}.item-row b{font-size:11px;display:block}.item-row small{color:#a7b6b5;font-size:9px}.item-row button{margin-left:auto;border:1px solid #d6bb7066;background:#d6bb7014;border-radius:5px;padding:7px 9px;color:#f0d492;font-size:9px}.panel-note{font-size:9px;color:#aab7b4;line-height:1.6}.start-screen{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(4,17,26,.76),rgba(4,17,26,.18)),linear-gradient(0deg,#07182499,transparent 55%);transition:opacity .6s,visibility .6s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:440px;margin-left:20%;margin-top:-10px;text-align:center;padding:30px;background:linear-gradient(135deg,#102838c9,#0a1d2bcc);border:1px solid #e6cb8866;border-radius:3px;box-shadow:0 18px 80px #00101d66;position:relative}.start-card:before,.start-card:after{content:'';position:absolute;width:18px;height:18px;border-color:#e8cb80;border-style:solid}.start-card:before{left:-1px;top:-1px;border-width:1px 0 0 1px}.start-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.start-emblem{font-size:22px;color:#e5c47c;margin-bottom:9px}.eyebrow{font-size:8px;letter-spacing:3px;color:#d3bc7d}.start-card h1{font:800 54px/.92 'Playfair Display',serif;letter-spacing:2px;margin:16px 0;color:#f3ecdb}.start-card h1 em{font-style:normal;color:#e7c879}.start-card p{font-size:12px;color:#c1ceca;margin:17px 0 24px}.start-card button{width:100%;padding:14px;background:#d8b962;border:0;border-radius:3px;color:#102536;font-size:10px;letter-spacing:1.8px;font-weight:800}.start-card button span{float:right;font-size:17px;line-height:10px}.start-card>small{display:block;color:#94a8a9;font-size:8px;margin-top:14px}.start-footer{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:2px;color:#b3c2bd;white-space:nowrap}.start-footer span{color:#dabc6c;margin:0 9px}.level-flash{position:absolute;z-index:9;left:50%;top:39%;transform:translate(-50%,-10px) scale(.8);opacity:0;display:flex;flex-direction:column;align-items:center;text-shadow:0 2px 15px #000}.level-flash.show{animation:levelpop 2s ease both}.level-flash span{font-size:36px;color:#f0cf75}.level-flash b{font:700 25px 'Playfair Display',serif;color:#f4d988;letter-spacing:2px}.level-flash small{font-size:8px;letter-spacing:3px;color:#f1e5c2;margin-top:5px}.touch-controls{display:none;position:absolute;z-index:4;bottom:24px;left:20px;right:20px;justify-content:space-between;align-items:end;pointer-events:none}.dpad,.touch-attack{pointer-events:auto}.dpad{display:flex;flex-direction:column;align-items:center;gap:3px}.dpad>div{display:flex;gap:3px}.dpad button,.touch-attack{width:43px;height:40px;border:1px solid #ffffff50;background:#0b263ba8;color:#f2e7c7;border-radius:8px;touch-action:none}.touch-attack{width:58px;height:58px;border-radius:50%;font-size:24px;background:#9c572cbb;border-color:#ffd18a99}.paused{filter:grayscale(.7)}@keyframes pop{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes levelpop{0%{opacity:0;transform:translate(-50%,10px) scale(.7)}15%,70%{opacity:1;transform:translate(-50%,0) scale(1)}100%{opacity:0;transform:translate(-50%,-15px) scale(1.05)}}
@media(max-width:700px){.topbar{height:60px;padding:0 12px}.brand{gap:7px}.brand-mark{width:31px;height:31px}.brand b{font-size:9px}.brand small{font-size:7px}.player-chip{left:auto;right:128px;transform:none;padding:5px 9px;min-width:auto}.player-chip strong{font-size:9px}.player-chip small{font-size:7px}.avatar-mini{width:27px;height:27px}.top-actions{gap:4px}.icon-btn{width:29px;height:29px;font-size:14px}.hud-left{left:10px;top:73px;width:min(192px,54vw);gap:7px}.status-card{padding:9px 10px}.quest-card{padding:9px 10px}.quest-card p{margin:7px 0}.quest-btn{margin-top:8px;padding:6px}.location-pill{top:68px;font-size:7px;padding:7px 10px;left:57%}.right-rail{right:9px;top:77px;gap:5px}.rail-button{width:42px;height:43px}.rail-button span{font-size:14px}.rail-button small{font-size:6px}.bottom-ui{bottom:14px}.hint{display:none}.hotbar{gap:4px}.hotkey{width:58px;height:58px}.hotkey small{font-size:6px}.slot-icon{font-size:21px}.touch-controls{display:flex}.panel{right:58px;top:73px;width:min(290px,calc(100vw - 80px));padding:16px}.start-card{width:min(390px,calc(100vw - 34px));margin:0;padding:24px 20px}.start-card h1{font-size:46px}.start-footer{font-size:7px;bottom:14px}.start-card>small{font-size:7px}.toast{top:64px}.level-flash{top:34%}}
@media(max-height:560px){.hud-left{top:80px}.status-card{padding:7px 10px}.meter{margin:4px 0 7px}.quest-card{padding:7px 10px}.quest-card p{margin:5px 0}.quest-btn{margin-top:5px;padding:5px}.hotkey{height:54px}.bottom-ui{bottom:8px}.hint{display:none}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
let W=innerWidth,H=innerHeight,dpr=1,last=0,now=0,running=false,paused=false,muted=true;
const world={w:2400,h:1800,cx:1200,cy:900};
let camera={x:world.cx,y:world.cy};
const player={x:world.cx,y:world.cy+115,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,coins:40,potions:2,speed:225,dir:0,attack:0,dash:0,invuln:0,fruit:'Ember',zcd:0,xcd:0,knockX:0,knockY:0};
const keys={},touch={up:false,down:false,left:false,right:false};
let enemies=[],effects=[],drops=[],decor=[],particles=[],quest=0,questKills=0,toastTimer=0,shake=0;
const quests=[{name:'Trouble on the shore',target:'Shoreline Rogues',need:4,reward:120,xp:80},{name:'A rough welcome',target:'Cove Bruisers',need:5,reward:190,xp:130},{name:'The captain’s challenge',target:'Blackwake Captain',need:1,reward:350,xp:220}];
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
function islandRadius(x,y){const dx=(x-world.cx)/890,dy=(y-world.cy)/690;return dx*dx+dy*dy}
function onIsland(x,y){return islandRadius(x,y)<1}
function createDecor(){decor=[];for(let i=0;i<78;i++){let x=rand(390,2010),y=rand(220,1580);if(onIsland(x,y)&&Math.hypot(x-world.cx,y-world.cy)>205)decor.push({x,y,type:Math.random()<.67?'palm':'bush',s:rand(.7,1.35),a:rand(0,6.28)})}for(let i=0;i<36;i++){let x=rand(340,2060),y=rand(240,1560);if(!onIsland(x,y))decor.push({x,y,type:'rock',s:rand(.5,1.25),a:rand(0,6.28)})}}
function makeEnemy(type,x,y){const captain=type==='captain',bruiser=type==='bruiser';return {type,x,y,r:captain?22:bruiser?18:15,hp:captain?260:bruiser?95:52,maxHp:captain?260:bruiser?95:52,speed:captain?65:bruiser?54:72,damage:captain?18:bruiser?12:8,attack:rand(.4,1.4),stun:0,flash:0,phase:rand(0,6),dead:false}}
function spawnQuestEnemies(){enemies=[];let q=quests[quest];for(let i=0;i<q.need;i++){let a=rand(0,6.28),r=rand(270,460),x=world.cx+Math.cos(a)*r,y=world.cy+Math.sin(a)*r;if(!onIsland(x,y)){x=world.cx+Math.cos(a)*250;y=world.cy+Math.sin(a)*250}enemies.push(makeEnemy(quest===2?'captain':quest===1?'bruiser':'rogue',x,y))}}
createDecor();spawnQuestEnemies();
function screenPos(x,y){return {x:x-camera.x+W/2,y:y-camera.y+H/2}}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}
function updateHud(){ $('level').textContent=player.level;$('hp-label').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('energy-label').textContent=`${Math.ceil(player.energy)} / ${player.maxEnergy}`;$('hp-fill').style.width=`${100*player.hp/player.maxHp}%`;$('energy-fill').style.width=`${100*player.energy/player.maxEnergy}%`;$('xp-label').textContent=`${player.xp} / ${player.level*100}`;$('xp-fill').style.width=`${100*player.xp/(player.level*100)}%`;$('potion-count').textContent=player.potions;
 const q=quests[quest];$('quest-title').textContent=q.name;$('quest-copy').textContent=quest===2?'Defeat the Blackwake Captain':`Defeat ${q.need} ${q.target}`;$('quest-count').textContent=`${questKills} / ${q.need}`;$('quest-fill').style.width=`${100*questKills/q.need}%`;$('slot-z').querySelector('small').textContent=player.fruit==='Ember'?'EMBER BURST':'FROST LANCE';$('slot-x').querySelector('small').textContent=player.fruit==='Ember'?'TIDAL RING':'GLACIAL NOVA';$('z-cd').style.transform=`scaleY(${clamp(player.zcd/5,0,1)})`;$('x-cd').style.transform=`scaleY(${clamp(player.xcd/8,0,1)})`;$('attack-cd').style.transform=`scaleY(${clamp(player.attack/.35,0,1)})`;}
function addXp(n){player.xp+=n;while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxEnergy+=8;player.energy=player.maxEnergy;player.speed+=4;$('level-flash').classList.remove('show');void $('level-flash').offsetWidth;$('level-flash').classList.add('show');toast(`LEVEL ${player.level} — stronger, faster, legendary!`)}}
function completeQuest(){const q=quests[quest];player.coins+=q.reward;addXp(q.xp);toast(`QUEST COMPLETE  +${q.reward} doubloons · +${q.xp} XP`);quest=Math.min(quest+1,quests.length-1);questKills=0;setTimeout(()=>{if(running)spawnQuestEnemies()},1700);updateHud()}
function killEnemy(e){if(e.dead)return;e.dead=true;questKills++;let coin=Math.round(rand(7,18));drops.push({x:e.x,y:e.y,type:'coin',value:coin,life:18});addXp(e.type==='captain'?120:e.type==='bruiser'?38:24);if(e.type==='captain')player.coins+=80;if(questKills>=quests[quest].need)completeQuest();updateHud()}
function hurtEnemy(e,damage,dx,dy){if(e.dead)return;e.hp-=damage;e.flash=.15;e.stun=.16;let n=Math.hypot(dx,dy)||1;e.x+=dx/n*14;e.y+=dy/n*14;effects.push({x:e.x,y:e.y,type:'hit',life:.28,max:.28});if(e.hp<=0)killEnemy(e)}
function attack(){if(!running||paused||player.attack>0)return;player.attack=.36;let candidates=enemies.filter(e=>!e.dead&&dist(e,player)<94).sort((a,b)=>dist(a,player)-dist(b,player));let target=candidates[0];if(target){let dx=target.x-player.x,dy=target.y-player.y;player.dir=Math.atan2(dy,dx);hurtEnemy(target,28+player.level*3,dx,dy)}effects.push({x:player.x,y:player.y,type:'slash',life:.24,max:.24,angle:player.dir});}
function power(type){if(!running||paused)return;let isZ=type==='z',cost=isZ?28:42,cd=isZ?5:8;if((isZ?player.zcd:player.xcd)>0){toast('That power is still recharging');return}if(player.energy<cost){toast('Not enough energy');return}player.energy-=cost;if(isZ)player.zcd=cd;else player.xcd=cd;let radius=isZ?180:250,damage=isZ?54:72;effects.push({x:player.x,y:player.y,type:isZ?'burst':'ring',life:isZ?.62:.85,max:isZ?.62:.85,radius,fruit:player.fruit});for(const e of enemies){if(!e.dead&&dist(e,player)<radius){let dx=e.x-player.x,dy=e.y-player.y;hurtEnemy(e,damage+player.level*5,dx,dy)}}for(let i=0;i<24;i++){let a=rand(0,Math.PI*2),r=rand(30,radius);particles.push({x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,vx:Math.cos(a)*rand(20,120),vy:Math.sin(a)*rand(20,120),life:rand(.35,.8),max:.8,color:isZ?(player.fruit==='Ember'?'#ff8b4e':'#8de4f0'):'#5bd6dc'})}shake=.15;updateHud()}
function usePotion(){if(player.potions<=0){toast('No healing tonics left');return}if(player.hp>=player.maxHp){toast('You are already at full vitality');return}player.potions--;player.hp=Math.min(player.maxHp,player.hp+45);effects.push({x:player.x,y:player.y,type:'heal',life:.8,max:.8});toast('Healing tonic used · +45 vitality');updateHud()}
function dash(){if(!running||paused||player.dash>0||(!keys.Space&&!keys[' ']))return;let dx=(keys.KeyD||touch.right?1:0)-(keys.KeyA||touch.left?1:0),dy=(keys.KeyS||touch.down?1:0)-(keys.KeyW||touch.up?1:0);if(!dx&&!dy){dx=Math.cos(player.dir);dy=Math.sin(player.dir)}let n=Math.hypot(dx,dy);player.knockX=dx/n*700;player.knockY=dy/n*700;player.dash=.22;effects.push({x:player.x,y:player.y,type:'dash',life:.28,max:.28})}
function update(dt){now+=dt;if(!running||paused)return;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);player.zcd=Math.max(0,player.zcd-dt);player.xcd=Math.max(0,player.xcd-dt);player.energy=Math.min(player.maxEnergy,player.energy+7*dt);
 let dx=(keys.KeyD||touch.right?1:0)-(keys.KeyA||touch.left?1:0),dy=(keys.KeyS||touch.down?1:0)-(keys.KeyW||touch.up?1:0),m=Math.hypot(dx,dy);if(m){dx/=m;dy/=m;player.dir=Math.atan2(dy,dx);let speed=player.speed*(player.dash>0?3.3:1);let nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(onIsland(nx,ny)){player.x=nx;player.y=ny}}if(player.dash>0){let nx=player.x+player.knockX*dt,ny=player.y+player.knockY*dt;if(onIsland(nx,ny)){player.x=nx;player.y=ny}}
