 // winding sandy footpath
 ctx.strokeStyle='#cdb77f';ctx.lineWidth=36;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(world.cx+20,world.cy+380);ctx.bezierCurveTo(world.cx+90,world.cy+240,world.cx-95,world.cy+115,world.cx+6,world.cy-12);ctx.bezierCurveTo(world.cx+120,world.cy-164,world.cx+255,world.cy-197,world.cx+324,world.cy-382);ctx.stroke();ctx.strokeStyle='#dcc896';ctx.lineWidth=22;ctx.stroke();
 // inlet and dock
 ctx.fillStyle='#328399';ctx.beginPath();ctx.ellipse(world.cx+548,world.cy+373,165,83,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d8c28e';ctx.beginPath();ctx.ellipse(world.cx+500,world.cy+335,204,62,-.42,0,Math.PI*2);ctx.fill();
