function drawDecor(){for(const d of decor){if(d.type==='palm')drawPalm(d);else if(d.type==='rock'){ctx.save();ctx.translate(d.x,d.y);ctx.scale(d.s,d.s);ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(4,8,17,8,0,0,6.3);ctx.fill();ctx.fillStyle='#7a8a7b';ctx.beginPath();ctx.ellipse(0,0,15,10,.4,0,6.3);ctx.fill();ctx.fillStyle='#a5af91';ctx.beginPath();ctx.ellipse(-3,-3,8,4,.4,0,6.3);ctx.fill();ctx.restore()}else{ctx.fillStyle='#0002';ctx.beginPath();ctx.ellipse(d.x+3,d.y+5,18*d.s,8*d.s,0,0,6.3);ctx.fill();ctx.fillStyle='#518253';ctx.beginPath();ctx.arc(d.x,d.y,14*d.s,0,6.3);ctx.fill();ctx.fillStyle='#7a9e60';ctx.beginPath();ctx.arc(d.x-5,d.y-5,7*d.s,0,6.3);ctx.fill()}}}
