 ctx.save();ctx.translate(world.cx+548,world.cy+375);ctx.rotate(-.43);for(let i=0;i<7;i++){ctx.fillStyle=i%2?'#825a3c':'#a2764c';ctx.fillRect(-7+i*13,-55,10,112);ctx.fillStyle='#d1a96e';ctx.fillRect(-15+i*13,-58,7,118)}ctx.restore();
