 ctx.save();ctx.translate(world.cx+710,world.cy+402);ctx.rotate(-.3);ctx.fillStyle='#533d31';ctx.beginPath();ctx.moveTo(-63,-14);ctx.lineTo(57,-14);ctx.lineTo(39,15);ctx.quadraticCurveTo(0,30,-43,12);ctx.closePath();ctx.fill();ctx.fillStyle='#c4a26c';ctx.beginPath();ctx.moveTo(-4,-8);ctx.lineTo(1,-79);ctx.lineTo(40,-8);ctx.closePath();ctx.fill();ctx.strokeStyle='#e5d6af';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(1,-80);ctx.lineTo(1,0);ctx.stroke();ctx.restore();
}
function drawCharacter(x,y,dir,hero=false,phase=0,flash=0){ctx.save();ctx.translate(x,y);if(hero)ctx.rotate(dir);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,14,18,8,0,0,6.3);ctx.fill();if(hero){ctx.fillStyle='#264e56';ctx.beginPath();ctx.ellipse(0,5,12,14,0,0,6.3);ctx.fill();ctx.fillStyle='#d6b783';ctx.beginPath();ctx.arc(0,-8,9,0,6.3);ctx.fill();ctx.fillStyle='#252f37';ctx.beginPath();ctx.ellipse(0,-12,13,5,0,0,6.3);ctx.fill();ctx.fillStyle='#3d2923';ctx.fillRect(-8,8,6,12);ctx.fillRect(3,8,6,12);ctx.strokeStyle='#dbd9c7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(5,2);ctx.lineTo(16,-11);ctx.stroke();ctx.strokeStyle='#e9cd7e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(13,-9);ctx.lineTo(20,-17);ctx.stroke();}else{let captain=player.type==='captain',bruiser=player.type==='bruiser';ctx.fillStyle=flash>0?'#fff':captain?'#533554':bruiser?'#a34f3c':'#a44f43';ctx.beginPath();ctx.ellipse(0,3,13,15,Math.sin(phase)*.07,0,6.3);ctx.fill();ctx.fillStyle='#d5a77d';ctx.beginPath();ctx.arc(0,-11,captain?9:8,0,6.3);ctx.fill();ctx.fillStyle=captain?'#292735':'#48382e';ctx.beginPath();ctx.ellipse(0,-16,11,5,0,0,6.3);ctx.fill();ctx.fillStyle='#eee1b7';ctx.fillRect(4,1,13,3);ctx.strokeStyle='#d7c19a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(11,7);ctx.lineTo(18,-3);ctx.stroke();if(captain){ctx.fillStyle='#e9c775';ctx.beginPath();ctx.moveTo(-7,-16);ctx.lineTo(-4,-25);ctx.lineTo(0,-17);ctx.lineTo(5,-26);ctx.lineTo(8,-16);ctx.fill()}}if(flash>0){ctx.globalCompositeOperation='screen';ctx.fillStyle=`rgba(255,255,255,${flash*3})`;ctx.beginPath();ctx.arc(0,0,20,0,6.3);ctx.fill()}ctx.restore()}
function drawEntities(){for(const e of enemies){if(e.dead)continue;let p=screenPos(e.x,e.y);drawCharacter(p.x,p.y,0,false,e.phase,e.flash);let bw=e.type==='captain'?48:34,by=p.y-34;ctx.fillStyle='#081820bb';ctx.fillRect(p.x-bw/2,by,bw,4);ctx.fillStyle=e.type==='captain'?'#d587b3':'#d96f60';ctx.fillRect(p.x-bw/2,by,bw*e.hp/e.maxHp,4);if(e.type==='captain'){ctx.fillStyle='#f0d99c';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('BLACKWAKE CAPTAIN',p.x,by-7)}}for(const d of drops){let p=screenPos(d.x,d.y);ctx.save();ctx.translate(p.x,p.y+Math.sin(now*5+d.x)*3);ctx.fillStyle='#e8ca76';ctx.shadowColor='#f9d77c';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(0,0,7,0,6.3);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#6a4a22';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('✦',0,3);ctx.restore()}}
function drawEffects(){for(const e of effects){let p=screenPos(e.x,e.y),t=1-e.life/e.max;ctx.save();if(e.type==='slash'){ctx.translate(p.x,p.y);ctx.rotate(e.angle);ctx.strokeStyle='#fff0c5';ctx.lineWidth=4*(1-t);ctx.shadowColor='#e1ce94';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(0,0,49,-.8,.85);ctx.stroke()}else if(e.type==='burst'||e.type==='ring'){let radius=e.radius*(e.type==='ring'?t:Math.sqrt(t));ctx.strokeStyle=e.fruit==='Ember'?'#ff9b53':'#76e0e6';ctx.lineWidth=e.type==='ring'?6*(1-t)+1:7*(1-t)+1;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=20;ctx.beginPath();ctx.arc(p.x,p.y,radius,0,6.3);ctx.stroke();if(e.type==='burst'){ctx.fillStyle=`rgba(250,142,73,${(1-t)*.16})`;ctx.beginPath();ctx.arc(p.x,p.y,radius*.7,0,6.3);ctx.fill()}}else if(e.type==='hit'||e.type==='hurt'){ctx.fillStyle=e.type==='hurt'?'#ff7777':'#ffe99a';ctx.globalAlpha=1-t;ctx.font='bold 18px sans-serif';ctx.textAlign='center';ctx.fillText(e.type==='hurt'?'!':'✦',p.x,p.y-18-t*20)}else if(e.type==='heal'){ctx.globalAlpha=1-t;ctx.fillStyle='#8de4c8';ctx.font='bold 24px sans-serif';ctx.textAlign='center';ctx.fillText('+',p.x,p.y-28-t*35)}else if(e.type==='dash'){ctx.strokeStyle='#a6ecdc';ctx.globalAlpha=1-t;ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(p.x,p.y,20+t*65,9+t*25,0,0,6.3);ctx.stroke()}ctx.restore()}for(const p of particles){let s=screenPos(p.x,p.y);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(s.x,s.y,2+3*p.life/p.max,0,6.3);ctx.fill()}ctx.globalAlpha=1}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);if(shake>0)ctx.translate(rand(-3,3),rand(-3,3));ctx.save();ctx.translate(W/2-camera.x,H/2-camera.y);drawWorld();drawEntities();drawEffects();let p=screenPos(player.x,player.y);if(player.invuln>0&&Math.floor(now*18)%2===0)ctx.globalAlpha=.45;drawCharacter(player.x,player.y,player.dir,true,now);ctx.globalAlpha=1; // local player nameplate
 ctx.restore();ctx.save();ctx.setLineDash([3,5]);ctx.strokeStyle='#fff6d633';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,player.dash>0?32:25,0,6.3);ctx.stroke();ctx.restore();requestAnimationFrame(frame)}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);render()}
requestAnimationFrame(frame);

