function openPanel(mode){const panel=$('panel'),box=$('panel-content');panel.classList.add('open');document.querySelectorAll('.rail-button').forEach(b=>b.classList.remove('active'));const active=mode==='inventory'?'inventory-btn':mode==='fruit'?'fruit-btn':'shop-btn';$(active)?.classList.add('active');if(mode==='inventory'){box.innerHTML=`<div class="eyebrow">YOUR JOURNEY</div><h2>Adventurer’s Bag</h2><p class="sub">A few essentials for a long voyage.</p><div class="item-row"><div class="item-art">✦</div><div><b>Doubloons</b><small>Collected from island rogues</small></div><strong style="margin-left:auto;color:#f0d492;font-size:12px">${player.coins}</strong></div><div class="item-row"><div class="item-art">♜</div><div><b>Healing tonic ×${player.potions}</b><small>Restores 45 vitality</small></div><button data-action="potion">USE</button></div><div class="item-row"><div class="item-art">❋</div><div><b>${player.fruit} essence</b><small>Equipped power · Z and X</small></div><button data-action="fruit">CHANGE</button></div><p class="panel-note">Find challengers around Palm Cove to earn experience and doubloons. Keep moving when they close in.</p>`}else if(mode==='fruit'){box.innerHTML=`<div class="eyebrow">UNUSUAL FRUIT</div><h2>Choose your power</h2><p class="sub">Essence reshapes your Z and X abilities.</p><div class="item-row"><div class="item-art" style="color:#ff9b53">✹</div><div><b>Ember Essence</b><small>Explosive burst + tidal ring</small></div>${player.fruit==='Ember'?'<strong style="margin-left:auto;color:#9be2c4;font-size:9px">EQUIPPED</strong>':'<button data-action="ember">180 ◈</button>'}</div><div class="item-row"><div class="item-art" style="color:#8de4f0">❄</div><div><b>Frost Essence</b><small>Frost lance + glacial nova</small></div>${player.fruit==='Frost'?'<strong style="margin-left:auto;color:#9be2c4;font-size:9px">EQUIPPED</strong>':'<button data-action="frost">180 ◈</button>'}</div><p class="panel-note">Your powers recharge over time. Ember favors a close burst; Frost leaves enemies chilled.</p>`}else if(mode==='shop'){box.innerHTML=`<div class="eyebrow">PALM COVE TRADING POST</div><h2>Island Supplies</h2><p class="sub">Spend your hard-earned doubloons wisely.</p><div class="item-row"><div class="item-art">♜</div><div><b>Healing tonic</b><small>Restores 45 vitality · 1 bottle</small></div><button data-action="buy-potion">35 ◈</button></div><div class="item-row"><div class="item-art">⬆</div><div><b>Training manual</b><small>+10 maximum vitality</small></div><button data-action="training">100 ◈</button></div><div class="item-row"><div class="item-art">❋</div><div><b>Frost Essence</b><small>A new set of elemental powers</small></div><button data-action="frost">180 ◈</button></div><p class="panel-note">Doubloons: <b style="color:#efd48c">${player.coins} ◈</b> · Defeat rogues for more.</p>`}else{box.innerHTML=`<div class="eyebrow">CHART OF PALM COVE</div><h2>Local waters</h2><p class="sub">A quiet island with a not-so-quiet shoreline.</p><div class="item-row"><div class="item-art">⌖</div><div><b>Current position</b><small>South beach · Palm Cove</small></div></div><div class="item-row"><div class="item-art">⚑</div><div><b>${quests[quest].name}</b><small>${Math.max(0,quests[quest].need-questKills)} targets remain nearby</small></div></div><p class="panel-note">Rogues gather in the island’s clearings. Follow the sandy trail to the trading post and eastern dock.</p>`}box.dataset.mode=mode}
function closePanel(){ $('panel').classList.remove('open');document.querySelectorAll('.rail-button').forEach(b=>b.classList.remove('active'));$('inventory-btn').classList.add('active')}
function buy(action){if(action==='potion'){usePotion();openPanel('inventory');return}if(action==='fruit'){openPanel('fruit');return}if(action==='ember'||action==='frost'){if(player.fruit===action[0].toUpperCase()+action.slice(1)){toast('You already carry that essence');return}if(player.coins<180){toast('You need 180 doubloons for an essence');return}player.coins-=180;player.fruit=action[0].toUpperCase()+action.slice(1);toast(`${player.fruit} essence equipped!`);openPanel('fruit');updateHud();return}if(action==='buy-potion'){if(player.coins<35){toast('Not enough doubloons');return}player.coins-=35;player.potions++;toast('Healing tonic added to your bag');openPanel('shop');updateHud();return}if(action==='training'){if(player.coins<100){toast('Not enough doubloons');return}player.coins-=100;player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+10);toast('Training complete · +10 max vitality');openPanel('shop');updateHud()}}
$('start-btn').addEventListener('click',()=>{$('start-screen').classList.add('hidden');running=true;last=performance.now();toast('Welcome to Palm Cove, sailor. Your quest awaits!')});
$('inventory-btn').addEventListener('click',()=>openPanel('inventory'));$('fruit-btn').addEventListener('click',()=>openPanel('fruit'));$('shop-btn').addEventListener('click',()=>openPanel('shop'));$('map-btn').addEventListener('click',()=>openPanel('map'));$('panel-close').addEventListener('click',closePanel);$('panel-content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)buy(b.dataset.action)});$('potion-btn').addEventListener('click',usePotion);$('quest-btn').addEventListener('click',()=>{toast(`TRACKING: ${quests[quest].name}`);openPanel('map')});$('touch-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('pause-btn').addEventListener('click',()=>{if(!running){$('start-screen').classList.remove('hidden');return}paused=!paused;$('pause-btn').textContent=paused?'▶':'Ⅱ';toast(paused?'Voyage paused':'Back to the adventure')});$('sound-btn').addEventListener('click',()=>{muted=!muted;$('sound-btn').textContent=muted?'♫':'♪';toast(muted?'Sound effects muted':'Sound effects enabled')});
canvas.addEventListener('pointerdown',e=>{if(e.button===0&&running&&!paused)attack()});
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyJ'||e.code==='Enter')attack();if(e.code==='KeyZ')power('z');if(e.code==='KeyX')power('x');if(e.code==='KeyQ')usePotion();if(e.code==='Space')dash();if(e.code==='Escape'){if($('panel').classList.contains('open'))closePanel();else if(running){paused=!paused;toast(paused?'Voyage paused':'Back to the adventure')}}});addEventListener('keyup',e=>{keys[e.code]=false});
document.querySelectorAll('.dpad button').forEach(btn=>{const direction=btn.dataset.dir;const prop={up:'up',down:'down',left:'left',right:'right'}[direction];btn.addEventListener('pointerdown',e=>{e.preventDefault();touch[prop]=true;btn.setPointerCapture(e.pointerId)});for(const type of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(type,()=>{touch[prop]=false})});
// Keep interaction state from leaking if the tab loses focus.
addEventListener('blur',()=>{for(const k in keys)keys[k]=false;for(const k in touch)touch[k]=false});
updateHud();
})();

