(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);let W=innerWidth,H=innerHeight,dpr=1,last=0,now=0,running=false,paused=false,muted=true;const world={w:2400,h:1800,cx:1200,cy:900};let camera={x:world.cx,y:world.cy};const player={x:world.cx,y:world.cy+115,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,coins:40,potions:2,speed:225,dir:0,attack:0,dash:0,invuln:0,fruit:'Ember',zcd:0,xcd:0,knockX:0,knockY:0};const keys={},touch={up:false,down:false,left:false,right:false};let enemies=[],effects=[],drops=[],decor=[],particles=[],quest=0,questKills=0,toastTimer=0,shake=0;const quests=[{name:'Trouble on the shore',target:'Shoreline Rogues',need:4,reward:120,xp:80},{name:'A rough welcome',target:'Cove Bruisers',need:5,reward:190,xp:130},{name:'The captain’s challenge',target:'Blackwake Captain',need:1,reward:350,xp:220}];const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();function islandRadius(x,y){const dx=(x-world.cx)/890,dy=(y-world.cy)/690;return dx*dx+dy*dy}function onIsland(x,y){return islandRadius(x,y)<1}
function createDecor(){decor=[];for(let i=0;i<78;i++){let x=rand(390,2010),y=rand(220,1580);if(onIsland(x,y)&&Math.hypot(x-world.cx,y-world.cy)>205)decor.push({x,y,type:Math.random()<.67?'palm':'bush',s:rand(.7,1.35),a:rand(0,6.28)})}for(let i=0;i<36;i++){let x=rand(340,2060),y=rand(240,1560);if(!onIsland(x,y))decor.push({x,y,type:'rock',s:rand(.5,1.25),a:rand(0,6.28)})}}
function makeEnemy(type,x,y){const captain=type==='captain',bruiser=type==='bruiser';return{type,x,y,r:captain?22:bruiser?18:15,hp:captain?260:bruiser?95:52,maxHp:captain?260:bruiser?95:52,speed:captain?65:bruiser?54:72,damage:captain?18:bruiser?12:8,attack:rand(.4,1.4),stun:0,flash:0,phase:rand(0,6),dead:false}}
function spawnQuestEnemies(){enemies=[];for(let i=0;i<quests[quest].need;i++){let a=rand(0,6.28),r=rand(270,460),x=world.cx+Math.cos(a)*r,y=world.cy+Math.sin(a)*r;if(!onIsland(x,y)){x=world.cx+Math.cos(a)*250;y=world.cy+Math.sin(a)*250}enemies.push(makeEnemy(quest===2?'captain':quest===1?'bruiser':'rogue',x,y))}}createDecor();spawnQuestEnemies();function screenPos(x,y){return{x:x-camera.x+W/2,y:y-camera.y+H/2}}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}function updateHud(){$('level').textContent=player.level;$('hp-label').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('energy-label').textContent=`${Math.ceil(player.energy)} / ${player.maxEnergy}`;$('hp-fill').style.width=`${100*player.hp/player.maxHp}%`;$('energy-fill').style.width=`${100*player.energy/player.maxEnergy}%`;$('xp-label').textContent=`${player.xp} / ${player.level*100}`;$('xp-fill').style.width=`${100*player.xp/(player.level*100)}%`; $('potion-count').textContent=player.potions;const q=quests[quest];$('quest-title').textContent=q.name;$('quest-copy').textContent=quest===2?'Defeat the Blackwake Captain':`Defeat ${q.need} ${q.target}`;$('quest-count').textContent=`${questKills} / ${q.need}`;$('quest-fill').style.width=`${100*questKills/q.need}%`;$('slot-z').querySelector('small').textContent=player.fruit==='Ember'?'EMBER BURST':'FROST LANCE';$('slot-x').querySelector('small').textContent=player.fruit==='Ember'?'TIDAL RING':'GLACIAL NOVA';$('z-cd').style.transform=`scaleY(${clamp(player.zcd/5,0,1)})`;$('x-cd').style.transform=`scaleY(${clamp(player.xcd/8,0,1)})`;$('attack-cd').style.transform=`scaleY(${clamp(player.attack/.35,0,1)})`}
function addXp(n){player.xp+=n;while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxEnergy+=8;player.energy=player.maxEnergy;player.speed+=4;$('level-flash').classList.remove('show');void $('level-flash').offsetWidth;$('level-flash').classList.add('show');toast(`LEVEL ${player.level} — stronger, faster, legendary!`)}}
function completeQuest(){const q=quests[quest];player.coins+=q.reward;addXp(q.xp);toast(`QUEST COMPLETE  +${q.reward} doubloons · +${q.xp} XP`);quest=Math.min(quest+1,quests.length-1);questKills=0;setTimeout(()=>{if(running)spawnQuestEnemies()},1700);updateHud()}
function killEnemy(e){if(e.dead)return;e.dead=true;questKills++;drops.push({x:e.x,y:e.y,type:'coin',value:Math.round(rand(7,18)),life:18});addXp(e.type==='captain'?120:e.type==='bruiser'?38:24);if(e.type==='captain')player.coins+=80;if(questKills>=quests[quest].need)completeQuest();updateHud()}
function hurtEnemy(e,damage,dx,dy){if(e.dead)return;e.hp-=damage;e.flash=.15;e.stun=.16;let n=Math.hypot(dx,dy)||1;e.x+=dx/n*14;e.y+=dy/n*14;effects.push({x:e.x,y:e.y,type:'hit',life:.28,max:.28});if(e.hp<=0)killEnemy(e)}
function attack(){if(!running||paused||player.attack>0)return;player.attack=.36;let candidates=enemies.filter(e=>!e.dead&&dist(e,player)<94).sort((a,b)=>dist(a,player)-dist(b,player)),target=candidates[0];if(target){let dx=target.x-player.x,dy=target.y-player.y;player.dir=Math.atan2(dy,dx);hurtEnemy(target,28+player.level*3,dx,dy)}effects.push({x:player.x,y:player.y,type:'slash',life:.24,max:.24,angle:player.dir})}
function power(type){if(!running||paused)return;let z=type==='z',cost=z?28:42,cd=z?5:8;if((z?player.zcd:player.xcd)>0){toast('That power is still recharging');return}if(player.energy<cost){toast('Not enough energy');return}player.energy-=cost;if(z)player.zcd=cd;else player.xcd=cd;let radius=z?180:250,damage=z?54:72;effects.push({x:player.x,y:player.y,type:z?'burst':'ring',life:z?.62:.85,max:z?.62:.85,radius,fruit:player.fruit});for(const e of enemies)if(!e.dead&&dist(e,player)<radius){let dx=e.x-player.x,dy=e.y-player.y;hurtEnemy(e,damage+player.level*5,dx,dy)}for(let i=0;i<24;i++){let a=rand(0,6.28),r=rand(30,radius);particles.push({x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,vx:Math.cos(a)*rand(20,120),vy:Math.sin(a)*rand(20,120),life:rand(.35,.8),max:.8,color:z?(player.fruit==='Ember'?'#ff8b4e':'#8de4f0'):'#5bd6dc'})}shake=.15;updateHud()}
function usePotion(){if(player.potions<=0){toast('No healing tonics left');return}if(player.hp>=player.maxHp){toast('You are already at full vitality');return}player.potions--;player.hp=Math.min(player.maxHp,player.hp+45);effects.push({x:player.x,y:player.y,type:'heal',life:.8,max:.8});toast('Healing tonic used · +45 vitality');updateHud()}
