 function update(dt){now+=dt;if(!running||paused)return;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);player.zcd=Math.max(0,player.zcd-dt);player.xcd=Math.max(0,player.xcd-dt);player.energy=Math.min(player.maxEnergy,player.energy+7*dt);let dx=(keys.KeyD||touch.right?1:0)-(keys.KeyA||touch.left?1:0),dy=(keys.KeyS||touch.down?1:0)-(keys.KeyW||touch.up?1:0),m=Math.hypot(dx,dy);if(m){dx/=m;dy/=m;player.dir=Math.atan2(dy,dx);let speed=player.speed*(player.dash>0?3.3:1),nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(onIsland(nx,ny)){player.x=nx;player.y=ny}}if(player.dash>0){let nx=player.x+player.knockX*dt,ny=player.y+player.knockY*dt;if(onIsland(nx,ny)){player.x=nx;player.y=ny}}
